package com.aoo.bcg.common.repair;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class IdempotentRepairExecutorTest{static class Store implements IdempotentRepairExecutor.Store<String>{Map<String,String>results=new HashMap<>();Set<String>running=new HashSet<>();public synchronized IdempotentRepairExecutor.Claim claim(String id,String hash){String k=id+hash;if(results.containsKey(k))return IdempotentRepairExecutor.Claim.COMPLETED;if(!running.add(k))return IdempotentRepairExecutor.Claim.IN_PROGRESS;return IdempotentRepairExecutor.Claim.ACQUIRED;}public Optional<String>completed(String id,String hash){return Optional.ofNullable(results.get(id+hash));}public void complete(String id,String hash,String r){running.remove(id+hash);results.put(id+hash,r);}public void fail(String id,String hash,String reason){running.remove(id+hash);}}@Test void rerunReturnsSameResultWithoutSecondMutation()throws Exception{var count=new AtomicInteger();var executor=new IdempotentRepairExecutor<String>(new Store());assertEquals("fixed",executor.execute("op-1","sha256:a",()->{count.incrementAndGet();return"fixed";}));assertEquals("fixed",executor.execute("op-1","sha256:a",()->{count.incrementAndGet();return"changed";}));assertEquals(1,count.get());}}
